<style>
.ai-workspace{display:flex;flex-direction:column;gap:20px;min-width:0}.ai-form-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,1fr);align-items:start;gap:24px;min-width:0}.ai-stack{display:flex;flex-direction:column;gap:20px;min-width:0}.ai-card{min-width:0;border:1px solid var(--theme-card-border-color);background:var(--theme-surface-base);border-radius:12px;scroll-margin-top:90px}.ai-card:focus{outline:2px solid var(--theme-accent);outline-offset:3px}.ai-card>header{padding:18px 20px;border-bottom:1px solid var(--theme-border-color)}.ai-card h2{font-size:15px;font-weight:600}.ai-card header p{font-size:12px;line-height:1.6;color:var(--theme-muted-text-color);margin-top:5px}.ai-card-body{padding:20px;display:flex;flex-direction:column;gap:16px;min-width:0}.ai-card-body>div{min-width:0}.ai-steps{display:flex;gap:8px;flex-wrap:wrap}.ai-steps button{display:flex;gap:10px;align-items:center;border:1px solid var(--theme-border-color);background:var(--theme-surface-base);border-radius:8px;padding:9px 14px;font-size:12px}.ai-steps span{color:var(--theme-accent);background:var(--theme-surface-soft);border-radius:5px;padding:2px 7px}.ai-advanced{border-top:1px solid var(--theme-border-color);padding-top:12px}.ai-advanced summary{font-size:12px;font-weight:600;color:var(--theme-accent);cursor:pointer;margin-bottom:12px}.ai-advanced[open]>*:not(summary){margin-top:12px}.ai-prompt-list{max-height:290px;overflow:auto;border:1px solid var(--theme-border-color);border-radius:8px}.ai-prompt{display:flex;align-items:start;gap:12px;padding:14px;border-bottom:1px solid var(--theme-border-color)}.ai-prompt:last-child{border:0}.ai-prompt label{display:flex;gap:12px;flex:1;min-width:0;font-size:12px;line-height:1.7;cursor:pointer;overflow-wrap:anywhere}.ai-prompt input{margin-top:4px;accent-color:var(--theme-accent)}.ai-prompt button{padding:5px;color:var(--theme-muted-text-color)}.ai-muted{font-size:12px;line-height:1.6;color:var(--theme-muted-text-color)}.ai-error{font-size:12px;color:var(--theme-danger-color)}.ai-error-summary{font-size:12px;line-height:1.6;padding:12px;background:var(--theme-surface-soft);border-left:3px solid var(--theme-danger-color);color:var(--theme-danger-color)}.ai-error-summary ul{list-style:disc;padding-left:16px;margin-top:6px}.ai-review{display:grid;gap:10px;font-size:12px}.ai-review>div{display:flex;justify-content:space-between;gap:16px}.ai-review dt{color:var(--theme-muted-text-color)}.ai-review dd{text-align:right;overflow-wrap:anywhere}.ai-note,.ai-cost{padding:13px;background:var(--theme-surface-soft);border-radius:8px;font-size:12px;line-height:1.6}.ai-cost p{color:var(--theme-muted-text-color);margin-top:4px}.ai-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.ai-days button{font-size:11px;padding:10px 0;border-radius:7px;min-width:0}.ai-card button:disabled{opacity:.45;cursor:not-allowed}.ai-caption{font:inherit;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--theme-surface-soft);padding:14px;border-radius:8px;max-height:320px;overflow:auto}.ai-preview-empty{text-align:center;padding:24px 8px;color:var(--theme-muted-text-color);font-size:12px}.ai-preview-empty i{font-size:25px;color:var(--theme-accent);margin-bottom:12px}
.ai-summary{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;color:var(--theme-muted-text-color)}.ai-summary strong{font-size:18px;color:var(--theme-header-text-color);margin-right:5px}.ai-toolbar{display:flex;gap:12px;align-items:center;padding:14px;background:var(--theme-surface-base);border:1px solid var(--theme-border-color);border-radius:12px}.ai-toolbar>div:first-child{flex:1;min-width:0}.ai-toolbar>div:last-child{min-width:165px}.ai-row{padding:18px 20px}.ai-row-heading{display:flex;align-items:start;gap:12px}.ai-row-title{flex:1;min-width:0}.ai-row-title h2{font-size:15px;font-weight:600;overflow-wrap:anywhere}.ai-badge{font-size:10px;padding:4px 8px;border-radius:6px;background:var(--theme-surface-soft);color:var(--theme-muted-text-color);white-space:nowrap}.ai-badge[data-state=enabled]{color:var(--theme-accent);background:rgba(var(--theme-accent-rgb),.1)}.ai-badge[data-state=attention]{color:var(--theme-danger-color)}.ai-row-meta{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:14px 0;margin:14px 0;border-block:1px solid var(--theme-border-color);font-size:12px}.ai-row-meta dt{font-size:11px;color:var(--theme-muted-text-color);margin-bottom:4px}.ai-row-meta dd{overflow-wrap:anywhere}.ai-row-bottom{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap}.ai-actions{display:flex;flex-wrap:wrap;gap:8px}.ai-actions .app-ui-button{font-size:12px;min-height:34px;padding:6px 11px}.ai-overlay{position:fixed;inset:0;z-index:180;background:rgba(15,23,42,.4);display:flex;align-items:center;justify-content:center;padding:20px}.ai-activity{max-height:85dvh;overflow:auto;width:min(760px,100%);border-radius:12px;background:var(--theme-surface-base);padding:22px}.ai-activity>header{display:flex;justify-content:space-between;gap:12px;margin-bottom:18px}.ai-activity h2{font-size:18px;font-weight:600}.ai-attempt{padding:14px 0;border-top:1px solid var(--theme-border-color);font-size:12px;line-height:1.7}.ai-attempt 